"""Build Module I using the released LING406 reader and study interface.

Only the Module I UI files are written. Authored content lives in data.js and
source preparation is a separate step. Every count comes from the loaded data.
"""
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
TEMPLATE=ROOT.parent/'module3'
app=(TEMPLATE/'app.js').read_text()
def replace_function(name,replacement):
 global app
 lines=app.splitlines(keepends=True)
 start=next(i for i,line in enumerate(lines) if line.startswith('function '+name+'('))
 end=start+1
 if not lines[start].rstrip().endswith('}'):
  while lines[end].rstrip('\n')!='}':end+=1
  end+=1
 app=''.join(lines[:start])+replacement.strip()+'\n'+''.join(lines[end:])
app=app.replace('window.LING406_MODULE3','window.LING406_MODULE1').replace('ling406-module3-study-studio-v1','ling406-module1-study-studio-v1').replace('LING406-ModuleIII-notes-and-progress.json','LING406-ModuleI-notes-and-progress.json')
app=app.replace("const state={notes:", "let legacyPreferences={};try{legacyPreferences=JSON.parse(localStorage.getItem('ling406-module1-preferences')||'{}')||{}}catch{}\nif(!stored.theme&&['light','dark'].includes(legacyPreferences.theme))stored.theme=legacyPreferences.theme;\nif(stored.sideClosed===undefined&&typeof legacyPreferences.sideClosed==='boolean')stored.sideClosed=legacyPreferences.sideClosed;\nconst state={notes:")
app=app.replace("selected=params.get('lecture')||'reading1'", "selected=params.get('lecture')||collections[0]?.id")
app=app.replace("if(!modules.has(selected))selected='reading1';", "if(!modules.has(selected))selected=collections[0]?.id;")
app=app.replace("const reviewModule=modules.get('review');", "const reviewModule=modules.get('review');\nconst collectionQuestions=id=>D.questions.filter(q=>q.module===id);\nconst examSize=()=>D.modules.reduce((n,m)=>n+Math.min(collectionQuestions(m.id).length,D.testAllocation?.[m.id]??collectionQuestions(m.id).length),0);")
replace_function('nav',r'''function nav(){
 $('#courseNav').innerHTML=`<button data-go="home" class="${view==='home'?'active':''}">Course overview</button><a class="button" href="./?view=home">Module I · Midterm 1</a><a class="button" href="../?view=home">Module II · Midterm 2</a><a class="button" href="../module3/?view=home">Module III · Final</a>`;
 $('#workNav').innerHTML=WORK.map(([id,title])=>`<button data-go="${id}" class="${view===id?'active':''}">${title}${id==='missed'?' · '+state.missed.length:''}</button>`).join('');
 $('#collectionNav').innerHTML=collections.map(m=>`<button data-lecture="${m.id}" class="${view==='collection'&&selected===m.id?'active':''}"><span class="nav-num">${esc(m.number)}</span>${esc(m.title)}</button>`).join('');
}''')
replace_function('home',r'''function home(){const count=D.sections.filter(s=>state.read[s.noteId||s.id]).length,total=D.sections.length;return `<span class="tag">MODULE I · MIDTERM 1</span><div class="hero"><span class="tag">LING406 · PSYCHOLINGUISTICS</span><h1>From speech sounds<br>to language and the brain.</h1><p>Phonetics and phonology, words and sentences, brains and language, the cognitive revolution, speech production, and experimental design. Study each original slide beside a direct teaching explanation, then practice applying its concepts and evidence.</p><div class="row"><button class="primary" data-lecture="${esc(collections[0].id)}">Begin with Lectures 1–2</button><button data-go="guide">Open the study guide</button><button data-go="written">Practice written explanations</button><button data-go="test">Take the current practice test</button></div></div><div class="grid"><div class="card"><span class="tag">CURRENT FOCUS</span><h2>Midterm 1</h2><p>${D.modules.length} collections · ${total} original pages · ${D.editions.length} teaching editions · ${D.questions.length} practice questions.</p><p class="small muted">${count} of ${total} pages marked read</p><div class="progress"><span style="width:${total?count/total*100:0}%"></span></div><button data-go="combined">Open combined notes</button></div><div class="card"><span class="tag">EXPERIMENTS & MODELS</span><h2>Explain what the evidence means</h2><p>Connect the task, comparison and result to the account of language it tests.</p><div class="row"><button data-go="experiments">Experiments to know</button><button data-go="core">Core review</button></div></div><div class="card"><span class="tag">COURSE MODULES</span><h2>Continue studying</h2><div class="row"><a class="button" href="../?view=home">Module II · Midterm 2</a><a class="button" href="../module3/?view=home">Module III · Final</a></div></div></div><div class="card"><h2>Read it. Teach it. Try it.</h2><p>Choose a teaching edition, explain the source visual, and test your understanding. Your notes stay attached to the same page across editions and views.</p><div class="row"><button data-go="quizzes">Choose a collection quiz</button><button data-review>Open Midterm 1 review</button><button data-go="written">Written practice</button></div></div><p class="small muted">Practice questions are original study material based on the supplied files. They are not instructor exam questions.</p>`}''')
replace_function('collection',r'''function collection(){const m=modules.get(selected),items=m.sections.map(id=>sections.get(id)),source=D.sources[m.source],count=collectionQuestions(m.id).length;return `<span class="tag">INDIVIDUAL COLLECTION ${esc(m.number)}</span><h1>${esc(m.title)}</h1><p>${items.length} original pages in source order, with ${D.editions.length} teaching editions, personal notes and read marks.</p><div class="row study-tools"><button data-reader="lecture">Visual + transcript</button>${expandButton('lecture')}<button data-quiz="lecture:${m.id}" ${count?'':'disabled'}>${count}-question collection quiz</button><a class="button" href="${source.file}" target="_blank" rel="noopener">Open original ${source.format.toUpperCase()}</a>${source.format==='pptx'?`<a class="button" href="${source.pdf}" target="_blank" rel="noopener">Open PDF rendition</a>`:''}</div>${searchTools('Search this collection')}${items.map(sectionHTML).join('')}`}''')
app=app.replace('60-question practice test','${examSize()}-question practice test').replace('across all six collections','across all ${D.modules.length} collections')
replace_function('test',r'''function test(){return `<span class="tag">CURRENT PRACTICE</span><h1>Test the explanation.<br>Use the evidence.</h1><p>The supplied Midterm 1 review describes ten open-book short essays, with about 100–250 words per answer. Practice writing explanations as well as checking concepts with the multiple-choice sets below.</p><div class="grid"><div class="card"><h2>${examSize()}-question practice test</h2><p>Questions cover the supplied Module I lectures and Midterm 1 review.</p><button class="primary" data-quiz="exam">Start ${examSize()}-question test</button></div><div class="card"><h2>A shorter mixed set</h2><p>A new selection each time, with explanations and source links after each response.</p><div class="row"><button data-quiz="mixed50">${Math.min(50,D.questions.length)} questions</button><button data-quiz="quick">${Math.min(10,D.questions.length)} questions</button></div></div><div class="card"><h2>Written explanation practice</h2><p>${D.written.length} prompts about concepts, methods, results, and explanations. Reveal the model answer after drafting a response.</p><button data-go="written">Open written practice</button></div></div><p class="small muted">Original practice based on the supplied materials. Choices are shuffled and validated before display.</p>`}''')
replace_function('quizzes',r'''function quizzes(){return `<h1>Lecture quizzes</h1><p>Each collection has its own source-linked questions. New sets reshuffle the questions and choices.</p><div class="grid">${D.modules.map(m=>{const count=collectionQuestions(m.id).length;return `<div class="card"><span class="tag">COLLECTION ${esc(m.number)}</span><h2>${esc(m.title)}</h2><div class="row"><button class="primary" data-quiz="lecture:${m.id}" ${count?'':'disabled'}>Start ${count}-question quiz</button><button data-lecture="${m.id}">Teaching notes</button></div></div>`}).join('')}</div>`}''')
replace_function('sources',r'''function sources(){return `<h1>Sources & coverage</h1><p>${Object.keys(D.sources).length} supplied files cover ${D.sections.length} original pages. Lectures 1 and 2 share one source deck. Each collection retains its source order, including title, divider and logistical pages.</p><div class="row study-tools"><button data-action="export">Export Module I notes & progress</button><a class="button" href="coverage-report.json">Coverage report</a><a class="button" href="source-manifest.json">Source manifest</a></div><div class="grid">${D.modules.map(m=>{const s=D.sources[m.source];return `<div class="card"><h2>${esc(m.title)}</h2><p>${s.pages} original pages · ${D.editions.length} teaching editions · ${collectionQuestions(m.id).length} questions.</p><a href="${s.file}">${esc(s.original)}</a>${s.format==='pptx'?`<p><a href="${s.pdf}">PDF rendition</a></p>`:''}<br><button data-lecture="${m.id}">Open collection</button></div>`}).join('')}</div><h2>Teaching editions</h2><div class="card">${D.editions.map(e=>`<p><strong>${esc(e.label)}</strong>${e.description?' · '+esc(e.description):''}</p>`).join('')}<p>Choose the edition in the transcript dropdown. All editions share the same original visuals, notes and read marks. Pages without instructional material retain their visuals without padded explanations.</p></div><h2>Practice and progress</h2><div class="card"><p>${D.questions.length} original questions and ${D.written.length} written prompts connect practice to the supplied sources. Core review selects concepts and evidence needed for the Midterm 1 review.</p><p>Module I notes, read marks and quiz progress stay in this browser and can be exported above. Modules II and III keep their own content and saved progress.</p></div>`}''')
app=app.replace('D.testAllocation[m.id]', '(D.testAllocation?.[m.id]??collectionQuestions(m.id).length)')
app=re.sub(r'var sourceMedia=\[.*?\n\];', 'var sourceMedia=D.media||[];', app, flags=re.S)
replace_function('mediaFor',r'''function mediaFor(s){const mapped=D.coverage?.reviewMappings?.[String(s.page)],id=s.source==='review'&&mapped?mapped:s.id;return sourceMedia.filter(m=>m.section===id).map(m=>`<div class="source-media">${m.type==='video'?`<video controls preload="metadata" src="${esc(m.url)}" aria-label="${esc(m.title)}" style="max-width:100%"></video>`:m.type==='audio'?`<audio controls preload="metadata" src="${esc(m.url)}" aria-label="${esc(m.title)}"></audio>`:''}<p><a class="button" href="${esc(m.url)}" target="_blank" rel="noopener">${esc(m.kind||'Source demonstration')} · ${esc(m.title)}</a></p></div>`).join('')}''')
replace_function('videoGallery',r'''function videoGallery(){return `<h1>Experiment videos & source demonstrations</h1>${sourceMedia.length?`<p>Open a supplied demonstration, then return to its matching source and explanation.</p><div class="grid">${sourceMedia.map(m=>`<article class="card"><h2>${esc(m.title)}</h2><p>${esc(m.kind||'Source demonstration')}</p>${mediaFor({id:m.section,source:sections.get(m.section)?.source,page:sections.get(m.section)?.page})}<button data-open-section="${m.section}">Matching slide + explanation</button></article>`).join('')}</div>`:'<p>The experiments and demonstrations in these files are available with their original figures and teaching explanations.</p>'}<button data-go="experiments">Open experiments</button>`}''')
app=app.replace("function stopAudio(){if('speechSynthesis'in window)speechSynthesis.cancel();window.LingAudio?.stop();window.LingVisual?.stop()}","function stopAudio(){if('speechSynthesis'in window)speechSynthesis.cancel();window.LingAudio?.stop();window.LingVisual?.stop();document.querySelectorAll('audio,video').forEach(media=>media.pause())}")
app=app.replace('// Template preview deliberately does not install an offline cache.', '// Module I uses a separate offline shell and saved-state key.')
assert 'reading1' not in app and 'Weeks 10' not in app and '185' not in app and 'Module III notes' not in app
app=app.replace("['test','Current practice test'],['quizzes'","['test','Current practice test'],['written','Written practice'],['quizzes'")
(ROOT/'app.js').write_text(app)
html=(TEMPLATE/'index.html').read_text().replace('Module III · Study Studio','Module I · Study Studio').replace('LING406 / MODULE III','LING406 / MIDTERM 1').replace('Psycholinguistics · Module III','Psycholinguistics · Module I')
html=re.sub(r'<details class="archive">.*?</details>','',html)
html=html.replace('data.js?v=module3-1','data.js?v=module1-1').replace('app.js?v=modules-2','app.js?v=module1-1').replace('app.js?v=module1-available-1','app.js?v=module1-1')
(ROOT/'index.html').write_text(html)
sw=(TEMPLATE/'sw.js').read_text().replace('ling406-module3-2','ling406-module1-1').replace('ling406-module3-3','ling406-module1-1').replace('data.js?v=module3-1','data.js?v=module1-1').replace('app.js?v=modules-2','app.js?v=module1-1').replace('app.js?v=module1-available-1','app.js?v=module1-1')
(ROOT/'sw.js').write_text(sw)
print('Built Module I interface from the existing LING406 Module III template.')
